def run_arm(samples, base, name, seed, out_dir, args, *, resume: bool = False):
    ablation = get_preset(name)
    config = ablation.apply_to_config(base).apply_overrides(seed=seed)
    arm_dir = out_dir / f"seed_{seed}" / name
    results_path = arm_dir / "results.jsonl"
    if resume:
        if not arm_dir.is_dir() or not results_path.is_file():
            raise FileNotFoundError(f"cannot resume missing arm dir: {arm_dir}")
        rows = _load_results_jsonl(results_path)
        done_ids = [r["sample_id"] for r in rows]
        if len(done_ids) != len(set(done_ids)):
            raise ValueError(f"duplicate sample_id in partial results: {arm_dir}")
        remaining = [s for s in samples if s.sample_id not in set(done_ids)]
        if not remaining:
            summary_path = arm_dir / "summary.json"
            if summary_path.is_file():
                return rows, json.loads(summary_path.read_text(encoding="utf-8"))
            raise RuntimeError(f"arm complete but missing summary.json: {arm_dir}")
        file_mode = "a"
    else:
        arm_dir.mkdir(parents=True, exist_ok=False)
        write_json(arm_dir / "config.json", {"config": asdict(config), "ablation": asdict(ablation)})
        rows = []
        remaining = samples
        file_mode = "x"
    write_json(arm_dir / "status.json", {"status": "running", "resume": resume, "n_completed": len(rows)})

